script:
stack=()
top=-1
RET=0
push() {
  top=$((top + 1))
  stack[$top]=$1
}
pop() {
  RET=${stack[$top]}
  unset 'stack[top]'
  top=$((top - 1))
}
apply() {
  local op=$1
  pop
  local b=$RET
  pop
  local a=$RET
  case "$op" in
    +) push $((a + b)) ;;
    -) push $((a - b)) ;;
  esac
}
push 10
push 5
apply +
push 3
apply -
echo "${stack[$top]}"
